from pathlib import Path

path = Path('schema/__init__.py')
text = path.read_text()
old = '''def _invoke_with_optional_kwargs(f: Callable[..., Any], **kwargs: Any) -> Any:
    return f(**kwargs)
    s = inspect.signature(f)
    if len(s.parameters) == 0:
        return f()

class Schema(object):
'''
new = '''def _invoke_with_optional_kwargs(f: Callable[..., Any], **kwargs: Any) -> Any:
    if not kwargs:
        return f()
    try:
        s = inspect.signature(f)
    except (TypeError, ValueError):
        # Some built-in callables do not have an inspectable signature.
        return f(**kwargs)
    if len(s.parameters) == 0:
        return f()
    return f(**kwargs)


class Schema(object):
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))

